const enc=new TextEncoder(),dec=new TextDecoder(),to64=a=>{let s='';for(const v of new Uint8Array(a))s+=String.fromCharCode(v);return btoa(s)},from64=s=>Uint8Array.from(atob(s),c=>c.charCodeAt(0));
const docNumberLabel=id=>id==='license'?'License number':id==='registration'?'Registration number':id==='insurance'?'Insurance policy number':'';
const fmt=n=>Number(n).toLocaleString('en-US');const esc=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
function cleanName(value){return String(value||'').replace(/[\u0000-\u001f\u007f]/g,'').trim().replace(/\s+/g,' ').slice(0,40);}
function profileName(data){return cleanName(data?.profile?.name);}
function welcome(name){return name?'Welcome back, '+name+'!':'Welcome back!';}
function timeGreeting(name,now=new Date()){const hour=now.getHours(),greeting=hour>=5&&hour<12?'Good morning':hour>=12&&hour<17?'Good afternoon':'Good evening';return greeting+(name?', '+name:'')+'!';}
