function hasDocumentSummary(id,d){return !!(docNumberLabel(id)&&d.number||id==='insurance'&&(d.insurer||d.expiry));}
function documentSummary(id,d,includeExpiry=true){return (id==='insurance'&&d.insurer?`<div class="doc-number insurer-name"><span>Insurance company</span><strong>${esc(d.insurer)}</strong></div>`:'')+(docNumberLabel(id)&&d.number?`<div class="doc-number"><span>${docNumberLabel(id)}</span><strong>${esc(d.number)}</strong></div>`:'')+(includeExpiry&&id==='insurance'&&d.expiry?`<div class="doc-number insurance-expiry"><span>Expiration date</span><strong>${esc(formatUSDate(d.expiry))}</strong></div>`:'');}
function formatUSDate(value){const match=/^(\d{4})-(\d{2})-(\d{2})$/.exec(String(value||''));return match?match[2]+'/'+match[3]+'/'+match[1]:'';}
