async function openDB(){db=await new Promise((resolve,reject)=>{const r=indexedDB.open('car-pocket-v1',1);r.onupgradeneeded=()=>r.result.createObjectStore('vault');r.onsuccess=()=>resolve(r.result);r.onerror=()=>reject(r.error)});const t=db.transaction('vault'),store=t.objectStore('vault');const read=k=>new Promise((res,rej)=>{const r=store.get(k);r.onsuccess=()=>res(r.result);r.onerror=()=>rej(r.error)});const [saved,name]=await Promise.all([read('main'),read('greeting')]);greetingName=cleanName(name);return saved;}
