$('#settings').onclick=()=>{modal(profileName(state)?profileName(state)+'’s wallet':'Your wallet',`<div class="wallet-profile"><span>What should I call you?</span><strong>${esc(profileName(state)||'Add your name')}</strong><button type="button" class="textbtn" id="editProfile">${profileName(state)?'Change name':'Add your name'} ↗</button></div><p class="modalnote">Documents and vehicle information are encrypted with your wallet password and saved in this browser on this device. They do not automatically sync to another phone or browser.</p><button class="secondary" id="backup">Export encrypted backup ↗</button><button class="secondary" id="restore">Restore encrypted backup</button><p class="small">Keep the backup in Files or iCloud Drive. You will need the password used when that backup was made. Clearing website data may erase this wallet. There is no password recovery.</p><p class="small">For Home Screen use, add the app first, then create or restore your wallet there. Safari and a Home Screen app may use separate storage. First access and sign-in require an internet connection; offline startup is not guaranteed.</p>`);$('#editProfile').onclick=()=>editProfile();$('#backup').onclick=async()=>{await queue;const blob=new Blob([JSON.stringify(record)],{type:'application/json'}),url=URL.createObjectURL(blob),a=document.createElement('a');a.href=url;a.download='car-pocket-backup-'+backupDate()+'.json';a.click();setTimeout(()=>URL.revokeObjectURL(url),30000);notify('Backup ready — save it in Files')};$('#restore').onclick=()=>$('#restoreFile').click()};
$('#gateRestore').onclick=()=>$('#restoreFile').click();$('#restoreFile').onchange=async e=>{const file=e.target.files[0];e.target.value='';if(!file)return;try{if(file.size>220*1024*1024)throw Error();const r=JSON.parse(await file.text());if(r.format!=='car-pocket'||r.version!==1||typeof r.cipher!=='string'||from64(r.salt).length!==16||from64(r.iv).length!==12)throw Error();if($('#modal').open)close();modal('Restore your wallet',`<p class="modalnote">This replaces the wallet on this device. Enter the password used for this backup.</p><form id="restoreForm">${field('Backup password','password','','password','required minlength="8"')}<button type="submit" class="primary">Unlock and restore backup</button><p class="error" id="restoreError" role="alert"></p></form>`);$('#restoreForm').onsubmit=async ev=>{ev.preventDefault();const b=ev.target.querySelector('button');b.disabled=true;try{const s=from64(r.salt),k=await derive(new FormData(ev.target).get('password'),s),data=await unseal(r,k);if(!data.vehicle||!data.oil||!data.docs)throw Error();await queue;await put(r,profileName(data));record=r;salt=s;key=k;state=data;greetingName=profileName(data);$('#gate').hidden=true;$('#app').hidden=false;$('#lock').hidden=false;render();close();notify('Wallet restored');if(!profileName(data))setTimeout(()=>{if(key&&state&&!$('#modal').open)editProfile(true)},0)}catch{$('#restoreError').textContent='Could not restore. Check the password and backup file.';b.disabled=false}}}catch{notify('This is not a supported Car Pocket backup.')}};
