let photoRequestId=0,photoBusy=false,photoMessage='',photoAttempt='';
function vehiclePhotoMode(v){return v.photoMode||(v.photo?.kind==='custom'?'custom':'auto');}
function ensureVehiclePhoto(){const v=state?.vehicle;if(!key||!v||photoBusy||vehiclePhotoMode(v)!=='auto'||v.photo?.data||!v.year||!v.make||!v.model)return;const signature=CarPhotos.signature(v);if(photoAttempt===signature)return;photoAttempt=signature;lookupVehiclePhoto();}

function renderCarPhoto(){const photo=state?.vehicle?.photo,img=$('#vehiclePhoto'),art=$('#carArt svg');const hasPhoto=photo&&/^data:image\/(jpeg|png|webp);base64,/.test(photo.data||'');img.hidden=!hasPhoto;art.style.display=hasPhoto?'none':'';if(hasPhoto){if(img.getAttribute('src')!==photo.data)img.src=photo.data;img.alt=photo.kind==='custom'?'Your vehicle photo':photo.title;}else img.removeAttribute('src');$('#photoCaption').textContent=photoBusy?'Finding a matching car photo…':hasPhoto?(photo.kind==='custom'?'Your own car photo':'Reference photo · color or trim may differ'):(photoMessage||'Generic illustration');}
async function lookupVehiclePhoto(){if(!state||!key)return;const v={...state.vehicle},signature=CarPhotos.signature(v);if(!v.year||!v.make||!v.model){photoMessage='Add year, make and model to find a photo.';renderCarPhoto();return}const request=++photoRequestId;photoAttempt=signature;photoBusy=true;photoMessage='';renderCarPhoto();const current=()=>request===photoRequestId&&!!key&&!!state&&CarPhotos.signature(state.vehicle)===signature&&vehiclePhotoMode(state.vehicle)==='auto';try{const matches=await CarPhotos.search(v);if(!current())return;if(!matches.length){photoMessage='No matching reference found. You can upload your own.';return}let photo;for(const match of matches.slice(0,3)){if(!current())return;try{photo=await CarPhotos.download(match);break}catch{}}if(!photo)throw Error('Could not download a matching photo.');if(!current())return;await commit(s=>current()?{...s,vehicle:{...s.vehicle,photo}}:s);notify('Matching reference photo saved')}catch{if(current())photoMessage='Photo lookup unavailable. Try again or upload a photo.'}finally{if(request===photoRequestId){photoBusy=false;if(state)renderCarPhoto()}}}
$('#managePhoto').onclick=()=>{const v=state.vehicle,p=v.photo,has=!!p?.data;modal('Your car photo',`${has?`<img class="photo-preview" id="managedPhotoPreview" role="button" tabindex="0" aria-label="Preview vehicle photo" src="${esc(p.data)}" alt="${esc(p.title||'Vehicle photo')}">`:''}<p class="modalnote">Find a reference photo for your year, make and model, or upload a photo of your actual car. Reference photos may have a different color, trim or regional specification.</p>${p?.kind==='web'?`<p class="photo-credit">${esc(p.title)}<br>Photo: ${esc(p.artist)} · ${esc(p.license)}${CarPhotos.trustedURL(p.licenseUrl,'creativecommons.org')?` · <a target="_blank" rel="noopener noreferrer" href="${esc(p.licenseUrl)}">License</a>`:''}<br>${CarPhotos.trustedURL(p.source,'commons.wikimedia.org')?`<a target="_blank" rel="noopener noreferrer" href="${esc(p.source)}">View original on Wikimedia Commons ↗</a>`:''}</p>`:''}<button class="primary" id="findPhoto" ${photoBusy?'disabled':''}>${photoBusy?'Searching…':'Find matching web photo ↗'}</button><p class="small">Only year, make, model and optional appearance details are used for web lookup. Your documents, plate and VIN are never sent.</p><label>Or upload your own photo<input type="file" id="uploadVehiclePhoto" accept="image/jpeg,image/png,image/webp"></label><p class="small">JPEG, PNG, or WebP up to 15 MB. Kept in your encrypted wallet and included in backups.</p>${has?'<button class="secondary" id="useIllustration">Use the generic illustration</button>':''}`);if($('#managedPhotoPreview')){const preview=()=>openImagePreview([{url:p.data,name:p.title||'Vehicle photo'}],0);$('#managedPhotoPreview').onclick=preview;$('#managedPhotoPreview').onkeydown=e=>{if(e.key==='Enter'||e.key===' '){e.preventDefault();preview()}};}$('#findPhoto').onclick=async()=>{if(!v.year||!v.make||!v.model){close();$('#editVehicle').onclick();notify('Add year, make and model first');return}try{photoAttempt=CarPhotos.signature(state.vehicle);await commit(s=>({...s,vehicle:{...s.vehicle,photoMode:'auto'}}));close();lookupVehiclePhoto()}catch{notify('Could not start photo lookup.')}};$('#uploadVehiclePhoto').onchange=async e=>{const file=e.target.files[0];if(!file)return;photoRequestId++;photoBusy=false;const signature=CarPhotos.signature(state.vehicle),button=$('#findPhoto');button.disabled=true;try{const photo=await CarPhotos.fromUpload(file);if(!state||!key||CarPhotos.signature(state.vehicle)!==signature)return;await commit(s=>({...s,vehicle:{...s.vehicle,photoMode:'custom',photo}}));photoMessage='';close();notify('Your car photo is saved')}catch(err){notify(err.message||'Could not save photo.');button.disabled=false}};if($('#useIllustration'))$('#useIllustration').onclick=async()=>{photoRequestId++;photoBusy=false;try{await commit(s=>{const vehicle={...s.vehicle,photoMode:'none'};delete vehicle.photo;return {...s,vehicle}});photoMessage='';close();notify('Using the illustration')}catch{notify('Could not update photo.')}}};
let previewGallery=[],previewIndex=0,previewZoom=1,previewFitWidth=0,previewFitHeight=0;
function closeImagePreview(){const dialog=$('#imagePreview');if(!dialog)return;if(dialog.open)dialog.close();clearImagePreview();}
function clearImagePreview(){previewGallery=[];$('#previewImage').onload=null;$('#previewImage').onerror=null;$('#previewImage').removeAttribute('src');$('#previewImage').alt='';$('#previewFilename').textContent='';}
function openImagePreview(gallery,index=0){previewGallery=gallery.slice();previewIndex=index;const dialog=$('#imagePreview');if(!dialog.open)dialog.showModal();showPreviewImage();}
function showPreviewImage(){const entry=previewGallery[previewIndex];if(!entry)return;const img=$('#previewImage');previewZoom=1;previewFitWidth=previewFitHeight=0;$('#previewFilename').textContent=entry.name;$('#previewPage').textContent=(previewIndex+1)+' / '+previewGallery.length;$('#previousImage').disabled=previewIndex===0;$('#nextImage').disabled=previewIndex===previewGallery.length-1;$('#previewImage').alt=entry.name;$('#zoomLevel').textContent='100%';$('#zoomOut').disabled=true;$('#zoomIn').disabled=true;img.onload=()=>fitPreviewImage();img.onerror=()=>{$('#previewPage').textContent='Unable to preview. Use Open / save in the document.';};img.src=entry.url;if(img.complete&&img.naturalWidth)fitPreviewImage();}
function fitPreviewImage(){const img=$('#previewImage'),stage=$('#previewStage');if(!img.naturalWidth)return;const ratio=Math.min((stage.clientWidth-32)/img.naturalWidth,(stage.clientHeight-32)/img.naturalHeight,1);previewFitWidth=Math.max(1,img.naturalWidth*ratio);previewFitHeight=Math.max(1,img.naturalHeight*ratio);setPreviewZoom(1);stage.scrollLeft=0;stage.scrollTop=0;}
function setPreviewZoom(value){if(!previewFitWidth)return;const stage=$('#previewStage'),x=(stage.scrollLeft+stage.clientWidth/2)/Math.max(1,stage.scrollWidth),y=(stage.scrollTop+stage.clientHeight/2)/Math.max(1,stage.scrollHeight);previewZoom=Math.max(1,Math.min(4,value));$('#previewImage').style.width=(previewFitWidth*previewZoom)+'px';$('#previewImage').style.height=(previewFitHeight*previewZoom)+'px';$('#previewCanvas').style.width=(previewFitWidth*previewZoom+32)+'px';$('#previewCanvas').style.height=(previewFitHeight*previewZoom+32)+'px';$('#zoomLevel').textContent=Math.round(previewZoom*100)+'%';$('#zoomOut').disabled=previewZoom<=1;$('#zoomIn').disabled=previewZoom>=4;stage.scrollLeft=x*stage.scrollWidth-stage.clientWidth/2;stage.scrollTop=y*stage.scrollHeight-stage.clientHeight/2;}
$('#closePreview').onclick=closeImagePreview;
$('#imagePreview').addEventListener('close',()=>{if(!$('#imagePreview').open)clearImagePreview();});
$('#imagePreview').onclick=e=>{if(e.target===$('#imagePreview'))closeImagePreview();};
$('#zoomIn').onclick=()=>setPreviewZoom(previewZoom+.5);
$('#zoomOut').onclick=()=>setPreviewZoom(previewZoom-.5);
$('#fitImage').onclick=fitPreviewImage;
$('#previousImage').onclick=()=>{if(previewIndex>0){previewIndex--;showPreviewImage();}};
$('#nextImage').onclick=()=>{if(previewIndex<previewGallery.length-1){previewIndex++;showPreviewImage();}};
$('#imagePreview').addEventListener('keydown',e=>{if(e.key==='ArrowLeft')$('#previousImage').click();else if(e.key==='ArrowRight')$('#nextImage').click();else if(e.key==='+'||e.key==='=')setPreviewZoom(previewZoom+.5);else if(e.key==='-')setPreviewZoom(previewZoom-.5);else if(e.key==='0')fitPreviewImage();else return;e.preventDefault();});
window.addEventListener('resize',()=>{if($('#imagePreview').open)fitPreviewImage();});
$('#vehiclePhoto').onclick=()=>{const img=$('#vehiclePhoto');if(!img.hidden)openImagePreview([{url:img.src,name:img.alt||'Vehicle photo'}],0);};
$('#vehiclePhoto').onkeydown=e=>{if(e.key==='Enter'||e.key===' '){e.preventDefault();$('#vehiclePhoto').click();}};

function editProfile(firstTime=false){modal(firstTime?'Make this wallet yours':'What should I call you?',`<p class="modalnote">${firstTime?'Add a first name or nickname for a more personal welcome.':'Choose how you would like to be greeted.'}</p><form id="editForm">${field('What should I call you?','name',profileName(state),'text','required maxlength="40" autocomplete="given-name" placeholder="Your first name or nickname"')}<p class="small">Your name is shown on this device’s locked welcome screen. Your profile is also included in your encrypted backup.</p><button type="submit" class="primary">Save my name ↗</button></form>`);bindForm(async f=>{const name=cleanName(f.get('name'));if(!name)throw Error('Please enter a name or nickname.');await commit(s=>({...s,profile:{...s.profile,name}}));});}

setInterval(()=>{if(!document.hidden)updateDashboardGreeting();},60000);
document.addEventListener('visibilitychange',()=>{if(!document.hidden)updateDashboardGreeting();});

function oilReminderStatus(o,v,now=new Date()){
 const mileageReady=o.last!==undefined&&o.interval>0&&v.mileage!==undefined;
 const remaining=mileageReady?Number(o.last)+Number(o.interval)-Number(v.mileage):null;
 let reminderDate=null;
 if(/^\d{4}-\d{2}-\d{2}$/.test(o.lastDate||'')){const [y,m,d]=o.lastDate.split('-').map(Number);const target=new Date(y,m-1+2,1);const finalDay=new Date(target.getFullYear(),target.getMonth()+1,0).getDate();reminderDate=new Date(target.getFullYear(),target.getMonth(),Math.min(d,finalDay));}
 const timeDue=!!reminderDate&&new Date(now.getFullYear(),now.getMonth(),now.getDate())>=reminderDate;
 return {remaining,reminderDate,timeDue,near:remaining!==null&&remaining<=700,overdue:remaining!==null&&remaining<=0};
}
function renderOilReminder(){
 if(!state||!key)return;
 const r=oilReminderStatus(state.oil,state.vehicle),box=$('#oilReminder');box.hidden=!(r.timeDue||r.near);box.classList.toggle('is-due',r.overdue);
 $('#oilReminderTitle').textContent=r.overdue?'Oil change due': 'Plan your next oil change';
 const messages=[];if(r.near)messages.push(r.remaining<0?fmt(-r.remaining)+' miles past your oil-change interval.':r.remaining===0?'You’ve reached your oil-change mileage.':fmt(r.remaining)+' miles remain until your next oil change.');if(r.timeDue)messages.push('It’s been at least 2 months since your last oil change.');$('#oilReminderText').textContent=messages.join(' ');
 $('#oilReminderSchedule').textContent='Reminder: 700 miles remaining'+(r.reminderDate?' or '+formatUSDate(calendarISO(r.reminderDate.getFullYear(),r.reminderDate.getMonth(),r.reminderDate.getDate())):'. Add your last oil-change date for a 2-month reminder')+'. Shown when your wallet is open; update your odometer regularly.';
}
$('#reviewOil').onclick=()=>$('#editOil').onclick();
setInterval(()=>{if(!document.hidden)renderOilReminder()},60000);
document.addEventListener('visibilitychange',()=>{if(!document.hidden)renderOilReminder()});

function odometerReminderDue(vehicle,now=Date.now()){
 const saved=Date.parse(vehicle.mileageUpdatedAt||'');
 return vehicle.mileage===undefined||!Number.isFinite(saved)||saved>now||now-saved>=5*24*60*60*1000;
}
function renderOdometerReminder(){
 if(!state||!key)return;
 const v=state.vehicle,hasVehicle=v.mileage!==undefined||v.make||v.model||v.year;
 $('#odometerReminder').hidden=!hasVehicle||!odometerReminderDue(v);
 const timestamp=Date.parse(v.mileageUpdatedAt||'');
 $('#odometerReminderText').textContent=Number.isFinite(timestamp)?'It’s been at least 5 days since your last reading. Enter your current mileage to keep your oil-change reminders accurate.':'Confirm your current mileage to start your 5-day update reminders.';
}
$('#refreshOdometer').onclick=()=>$('#updateMileage').onclick();
setInterval(()=>{if(!document.hidden)renderOdometerReminder()},60000);
document.addEventListener('visibilitychange',()=>{if(!document.hidden)renderOdometerReminder()});
